import{z as l,x as n,o as m,c as d,q as r,j as o,D as t,d as e,s as E,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"tmpfs","description":"","frontmatter":{"title":"tmpfs","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tmpfs.md","filePath":"cs/tmpfs.md","lastUpdated":1791413859000}'),f={name:"cs/tmpfs.md"};function B(A,a,c,h,u,D){const p=n("Mermaid");return m(),d("div",null,[a[2]||(a[2]=r('<h1 id="tmpfs" tabindex="-1">tmpfs <a class="header-anchor" href="#tmpfs" aria-label="Permalink to &quot;tmpfs&quot;">​</a></h1><div class="epigraph"><p>tmpfs 把页缓存当成唯一存储：inode 与数据都在内存，交换出去才落到交换设备，卸载即逝。</p><footer>—— 据 Snyder, tmpfs: A Virtual Memory File System；Linux tmpfs/shmem 文档</footer></div><p><a href="/cs/rename-atomicity">上一课</a>的原子改名对内存树同样成立，只是没有日志设备。<a href="/cs/page-cache">页缓存</a> 对普通文件是「盘的缓存」；tmpfs 反过来：<strong>文件就是页</strong>。缺口是 shmem/tmpfs 如何接 VFS 与虚存，包括 <code>/dev/shm</code> 与 POSIX 共享内存。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>管道与套接字不是目录树。需要可 <code>mmap</code>、可有名字、可限额的内存文件：构建目录、密卷、容器根的一层。tmpfs 挂在 VFS 上，超级块在内存，块分配器是 <code>shmem</code> 的页。缺口：容量上限（<code>size=</code>）与 <a href="/cs/memcg">memcg</a> 的交叉；内存压力下页可进 swap，于是「内存 FS」仍可能读盘；不进 swap 的锁定页是另一旋钮。</p><p><span class="marginnote">ramfs 通常不换出、不限额，可把机器撑死。tmpfs 有大小上限。教学上以 tmpfs 为准。</span></p><p><span class="marginnote">直觉类比：tmpfs 是限重的行李箱，超重部分塞进 swap 后备箱；ramfs 是不限重也不肯卸的行李——塞多少吃多少内存，直到机器撑死。教学选 tmpfs，正因为它有这个泄压阀。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>write</code>：分配页，插入 inode 页树，不调用 <code>readpage</code> 去块设备。<code>mmap</code> 共享即映射这些页，与 <a href="/cs/fs-mmap-coherence">mmap 一致</a> 同一帧。<code>rename</code> 只改内存 dentry。对照 <a href="/cs/f2fs">F2FS</a>：没有 NAT 下盘。对照 <a href="/cs/overlayfs">overlay</a>：upper 常常是一块 tmpfs，copy-up 的可写层随容器消失。</p>',9)),(m(),o(i,null,{default:t(()=>[E(p,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20WR%5B%22write%22%5D%20--%3E%20PG%5B%22shmem%20%E9%A1%B5%22%5D%0A%20%20PG%20--%3E%20TREE%5B%22inode%20%E9%A1%B5%E6%A0%91%22%5D%0A%20%20PRESS%5B%22%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%22%5D%20--%3E%20SW%5B%22%E5%8F%AF%E6%8D%A2%E5%87%BA%E5%88%B0%20swap%22%5D%0A%20%20UMNT%5B%22umount%22%5D%20--%3E%20GONE%5B%22%E9%A1%B5%E9%87%8A%E6%94%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[e("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,[e("tmpfs 证明 VFS 不绑定「块设备」：操作表填的是内存。它把 POSIX 文件接到 "),s("a",{href:"/cs/buddy-allocator"},"buddy"),e(" / 页回收，使 IPC（共享内存对象）与 "),s("code",null,"/tmp"),e(" 加速成为同一实现。不要把 tmpfs 写成数据库内存表：没有 WAL，崩溃丢失是语义。")],-1)),a[5]||(a[5]=s("p",null,"快照：除非下层是 COW 且 tmpfs 不在那层，普通 tmpfs 无持久快照。",-1)),a[6]||(a[6]=s("p",null,[e("实现上：size 上限按页，大页 THP 会使实际占用跳变。swap 启用时「内存 FS」仍可能读盘，mlock 的 tmpfs 页才真正钉住。/dev/shm 与 POSIX shm_open 走同一 shmem。 读法上只引用"),s("a",{href:"/cs/rename-atomicity"},"上一课"),e("的结论，不把对象换成训练推理或限价簿。")],-1)),(m(),o(i,null,{default:t(()=>[E(p,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%20write%20%E8%B0%83%E7%94%A8%22%5D%20--%3E%20Q%7B%22%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E5%90%8E%E7%AB%AF%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E7%A3%81%E7%9B%98%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%22%7C%20D%5B%22%E9%A1%B5%E7%BC%93%E5%AD%98%20%2B%20%E5%9D%97%E8%AE%BE%E5%A4%87%2C%E6%8C%81%E4%B9%85%22%5D%0A%20%20Q%20--%3E%7C%22tmpfs%22%7C%20T%5B%22shmem%20%E5%86%85%E5%AD%98%E9%A1%B5%2C%E5%8F%97%20size%20%E9%99%90%E9%A2%9D%22%5D%0A%20%20Q%20--%3E%7C%22ramfs%22%7C%20R%5B%22%E7%BA%AF%E5%86%85%E5%AD%98%E9%A1%B5%2C%E4%B8%8D%E6%8D%A2%E5%87%BA%E4%B9%9F%E4%B8%8D%E9%99%90%E9%A2%9D%22%5D%0A%20%20T%20--%3E%20L%7B%22%E9%81%87%E5%88%B0%E5%86%85%E5%AD%98%E5%8E%8B%E5%8A%9B%3F%22%7D%0A%20%20L%20--%3E%7C%22%E6%9C%89%22%7C%20SW%5B%22%E9%A1%B5%E8%A2%AB%E6%8D%A2%E5%87%BA%E5%88%B0%20swap%22%5D%0A%20%20L%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20STAY%5B%22%E9%A1%B5%E7%95%99%E5%9C%A8%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">数字实例：<code>mount -t tmpfs -o size=1G tmp /mnt</code> 声明的 1 GiB 是上限不是预分配。写一个 4 KiB 的小文件，实际只占约 4 KiB 加少量元数据；size 只是天花板，按页逐个计费。</span></p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>tmpfs</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 huge-tmpfs、DAX tmpfs 的全部页大小。不保证 NUMA 放置策略——<a href="/cs/numa-mempolicy">NUMA 策略</a> 在内存进阶。下一课把「不是普通文件」的 inode 钉住：设备节点。</p><p>版本字段会变，课序钉的是机制对象「tmpfs」，不是某一主线内核的结构体名。 后课默认：可挂载的内存树走 shmem。字符/块设备如何作为目录项出现，下一课设备节点。</p><p><span class="marginnote">常见误区：以为 tmpfs「在内存里」就绝不会碰盘。启用 swap 后，内存压力下它的页照样落到交换设备；而没有 WAL 的它，掉电即丢本来就是语义——拿 tmpfs 当数据库内存表用，是范畴错误。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tmpfs 用页缓存当数据，可换出，卸载即空。</li><li>与 ramfs 的差别主要是限额与换出。</li><li>设备节点是下一课。</li><li>出处：Snyder, tmpfs；Linux shmem；McKusick 对内存 FS 的对照。</li></ul>',9))])}const T=l(f,[["render",B]]);export{C as __pageData,T as default};
